  function about(){return `<article class="about-page page-enter v2-prose"><a class="back" href="#/">← ${tr('返回首页','Back home')}</a><span class="eyebrow">ABOUT ME / JANICE QIU</span>${copyHTML(tr(data.v2.about,data.v2.aboutEn)).replace('<h2>','<h1>').replace('</h2>','</h1>')}<div class="hero-contact"><a class="chip" href="mailto:${data.email}">${tr('联系我','Contact me')} ↗</a><a class="chip" href="#/resume">${tr('查看简历','Resume')} ↗</a><a class="chip" href="#/lab">Creative Lab ↗</a></div></article>`;}

